import{_ as o,o as s,c as t,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"LLM models","description":"","frontmatter":{"title":"LLM models"},"headers":[],"relativePath":"docs/concepts/llm-models.md","filePath":"docs/concepts/llm-models.md","lastUpdated":1794508483000}'),r={name:"docs/concepts/llm-models.md"};function d(n,e,l,i,h,m){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="llm-models" tabindex="-1">LLM models <a class="header-anchor" href="#llm-models" aria-label="Permalink to &quot;LLM models&quot;">​</a></h1><p>Models power chat and question-answering in OrbySystems. You can change which one you use at any time in <a href="/docs/settings/models">Settings → Models</a>.</p><h2 id="the-orbysystems-models" tabindex="-1">The OrbySystems models <a class="header-anchor" href="#the-orbysystems-models" aria-label="Permalink to &quot;The OrbySystems models&quot;">​</a></h2><p><strong>OrbySystems Small</strong>, <strong>OrbySystems Medium</strong> and <strong>OrbySystems Large</strong> are the models OrbySystems is built and tested for. They run entirely on your own computer, so nothing you ask, and none of your data, leaves it. <a href="/docs/overview/hardware-requirements">Hardware requirements</a> says which one suits your computer.</p><h2 id="other-models" tabindex="-1">Other models <a class="header-anchor" href="#other-models" aria-label="Permalink to &quot;Other models&quot;">​</a></h2><p>You can choose a different model instead: a larger open-source model that runs on your computer, a model you run yourself with software such as LM Studio, or a cloud model from an AI provider. OrbySystems isn&#39;t tested with these, so its answers can be less reliable.</p><h2 id="cloud-models" tabindex="-1">Cloud models <a class="header-anchor" href="#cloud-models" aria-label="Permalink to &quot;Cloud models&quot;">​</a></h2><p>A cloud model runs on someone else&#39;s servers: the state-of-the-art models from the leading AI providers. Using one means sending it what you&#39;d otherwise keep on your computer: your questions, and the project data it reads to answer them.</p><p>That provider&#39;s terms of service govern what they say they&#39;ll do with what you send, but terms can change, and by the time they do, your data is already with them. It&#39;s also subject to the same risks as any data held by a third party: a leak or breach, whether from an outside attacker or someone inside the company. Weigh that before choosing a cloud model. The <strong>AI Model</strong> card in the sidebar always shows where the model you&#39;re using runs; see <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Models and your data</a>.</p><h2 id="choosing-and-testing-a-model" tabindex="-1">Choosing and testing a model <a class="header-anchor" href="#choosing-and-testing-a-model" aria-label="Permalink to &quot;Choosing and testing a model&quot;">​</a></h2><p>See <a href="/docs/settings/models">Models</a> for how to choose one, and <a href="/docs/tools/model-test">Model Test</a> for checking that a model works well before relying on it.</p>',11)])])}const y=o(r,[["render",d]]);export{u as __pageData,y as default};
